const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const folders=['01-openable-formats','02-image-preview','03-unsupported-formats','04-large-document-performance','05-wysiwyg-roundtrip','06-math-katex','07-diagrams','08-frontmatter','09-export','10-file-tree-workspace','11-settings-document-limits','docs','evidence','manifests','tools'];
function renderFiles(){ const rows=folders.map(n=>`<div class="file-row"><svg class="tree-chevron" viewBox="0 0 24 24"><path d="m9 18 6-6-6-6"/></svg><svg class="folder-icon" viewBox="0 0 24 24"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg><span>${n}</span></div>`).join(''); $('#side-content').innerHTML=`<div class="tree-header"><button class="tree-chevron-btn" aria-label="收起所有文件夹"><svg viewBox="0 0 24 24"><path d="m6 9 6 6 6-6"/></svg></button><span class="tree-header-name">markflow-test</span><div class="tree-header-actions"><button class="tree-header-action" title="新建文件"><svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg></button><button class="tree-header-action" title="新建文件夹"><svg viewBox="0 0 24 24"><path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3zM12 11v6m-3-3h6"/></svg></button><button class="tree-header-action" title="刷新"><svg viewBox="0 0 24 24"><path d="M20 11a8 8 0 0 0-14-5L4 8m0-5v5h5M4 13a8 8 0 0 0 14 5l2-2m0 5v-5h-5"/></svg></button><button class="tree-header-action" title="展开所有文件夹"><svg viewBox="0 0 24 24"><path d="m7 10 5 5 5-5M7 5l5 5 5-5"/></svg></button></div></div>${rows}<div class="file-row tree-file"><svg class="tree-icon" viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/></svg><span>HANDOVER.md</span></div><div class="file-row tree-file"><svg class="tree-icon" viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/></svg><span>README.md</span></div>`; $('#side-content').querySelectorAll('.tree-chevron-btn,.tree-header-name').forEach(b=>b.onclick=()=>{$$('.tree-children').forEach(n=>n.hidden=true)}); }
function renderOutline(){ $('#side-content').innerHTML='<div class="empty-state" style="padding:12px 18px;color:var(--muted);font-size:12px">当前文档无标题</div>'; }
renderFiles();
$$('.side-switch button').forEach(b=>b.onclick=()=>{ $$('.side-switch button').forEach(x=>x.classList.toggle('selected',x===b)); b.dataset.side==='files'?renderFiles():renderOutline(); });
$('#sidebar-toggle').onclick=()=>$('#app').classList.toggle('sidebar-hidden');
$('#brand-menu').onclick=()=>$('#brand-popover').hidden=!$('#brand-popover').hidden;
document.addEventListener('click',e=>{if(!e.target.closest('.brand-wrap'))$('#brand-popover').hidden=true});
function toast(s){const t=$('#toast');t.textContent=s;t.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.hidden=true,1800)}
$$('[data-toast]').forEach(b=>b.onclick=()=>toast(b.dataset.toast));
$('#save-doc').onclick=()=>toast('已保存');$('#new-doc').onclick=$('#new-tab').onclick=()=>{const n=$$('.tab').length+1;const t=document.createElement('div');t.className='tab active';t.innerHTML=`未命名 ${n} <button class="tab-close">×</button>`;$('.tab.active')?.classList.remove('active');$('.tabs').insertBefore(t,$('#new-tab'));bindTab(t);$('#editor').innerHTML='<div class="placeholder">开始写作 — 输入即所得</div>';updateStats()};
function bindTab(t){t.onclick=e=>{if(e.target.matches('.tab-close')){if($$('.tab').length>1)t.remove();else toast('至少保留一个文档');return}$$('.tab').forEach(x=>x.classList.toggle('active',x===t))};} $$('.tab').forEach(bindTab);
$('#mode-source').onclick=()=>{ $('#mode-source').classList.add('active');$('#mode-visual').classList.remove('active');$('#mode-label').textContent='源码模式';$('#editor').classList.add('source-mode')};
$('#mode-visual').onclick=()=>{ $('#mode-visual').classList.add('active');$('#mode-source').classList.remove('active');$('#mode-label').textContent='所见即所得';$('#editor').classList.remove('source-mode')};
$('#focus-mode').onclick=$('#status-focus').onclick=()=>$('#app').classList.toggle('focus-mode');
let theme=0;const themes=['light','dark','sepia'];let followSystemTheme=false;
function setPaletteFamily(id){if(!/^[a-z0-9][a-z0-9-]{0,47}$/.test(id)||(!['github','notion','vue','feishu'].includes(id)&&!window.hasThemeFamily?.(id)))return;document.documentElement.dataset.palette=id;window.onThemePaletteChanged?.(id,themes[theme]);syncAppearanceControls();const popover=$('.theme-quick-popover');if(popover)popover.hidden=true;const button=$('.theme-quick-button');if(button)button.setAttribute('aria-expanded','false')}
window.setPaletteFamily=setPaletteFamily;
function syncAppearanceControls(){ $$('.appearance-mode-option').forEach(b=>{const selected=b.dataset.mode===themes[theme];b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});const follow=$('[data-follow-system]');if(follow){follow.classList.toggle('active',followSystemTheme);follow.setAttribute('aria-checked',String(followSystemTheme));}$$('.theme-family-card').forEach(b=>{const selected=b.dataset.palette===(document.documentElement.dataset.palette||'github');b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});$$('.theme-quick-option').forEach(b=>b.setAttribute('aria-checked',String(b.dataset.palette===(document.documentElement.dataset.palette||'github')))); }
window.syncAppearanceControls=syncAppearanceControls;
function setAppearanceMode(mode,manual=true){if(!themes.includes(mode))return;theme=themes.indexOf(mode);document.documentElement.dataset.theme=mode;window.onThemePaletteChanged?.(document.documentElement.dataset.palette||'github',mode);if(manual&&followSystemTheme)followSystemTheme=false;syncAppearanceControls();const button=$('#theme-cycle');if(button&&window.alineIcon)button.innerHTML=window.alineIcon(['sun','moon','eye'][theme]);}
window.setAppearanceMode=setAppearanceMode;
window.cycleAppearanceMode=()=>setAppearanceMode(themes[(theme+1)%themes.length],true);
document.documentElement.dataset.palette='github';
const systemAppearance=window.matchMedia?.('(prefers-color-scheme: dark)');
systemAppearance?.addEventListener('change',event=>{if(followSystemTheme)setAppearanceMode(event.matches?'dark':'light',false)});
$('#editor').addEventListener('input',()=>{if($('#editor').querySelector('.placeholder'))$('#editor .placeholder').classList.remove('placeholder');updateStats()});
$('#editor').addEventListener('keyup',updateStats);$('#editor').addEventListener('click',updateStats);
function updateStats(){let text=$('#editor').innerText.replace('开始写作 — 输入即所得','');$('#words').textContent=`${[...text.trim()].filter(c=>!/\s/.test(c)).length} 字`;$('#lines').textContent=`${Math.max(1,text.split('\n').length)} 行`;const sel=getSelection();if(sel&&sel.anchorNode){const r=document.createRange();r.selectNodeContents($('#editor'));r.setEnd(sel.anchorNode,sel.anchorOffset);const before=r.toString();const lines=before.split('\n');$('#cursor').textContent=`行 ${lines.length}, 列 ${[...lines.at(-1)].length}`}}
$('#settings-open').onclick=$('#status-settings').onclick=()=>openSettings();$('#settings-close').onclick=()=>$('#settings-backdrop').hidden=true;$('#settings-backdrop').onclick=e=>{if(e.target.id==='settings-backdrop')e.currentTarget.hidden=true};
function page(title,desc,body){return `<section class="settings-page" id="settings-page-${title}" data-settings-page="${title}"><h2>${title}</h2><p class="settings-intro">${desc}</p>${body}</section>`}
function group(title,body){return `<section class="settings-group"><div class="settings-group-heading"><h3 class="settings-group-title">${title}</h3><button class="settings-reset" type="button">恢复默认</button></div>${body}</section>`}
